import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-03-01","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-03-01","date":"2023-03-01T00:00:00.000Z","updated":"2023-03-07T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","同步策略","SSL兼容性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-01.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-01.md","lastUpdated":1780460162000}'),i={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-01.md"};function n(l,t,s,g,h,_){return a(),r("div",null,[...t[0]||(t[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>Reef 分支决策</strong>: 会议决定分叉 Reef 发布分支，预计当天完成。所有后续改动需合并至 Main 分支并通过 backboards。</li><li><strong>同步策略问题</strong>: 发现即使只有两个区域配置同步，第三个区域仍在拉取数据，这表明可能存在回归问题。此外，日志修剪和归档区域也存在问题，影响了日志的修剪。</li><li><strong>rgwhttp 客户端</strong>: 讨论了新的 rgwhttp 客户端类，可能对多站点配置和 HTTP/3 前端很有用。主要挑战是处理 OpenSSL 和 BoringSSL 的链接问题。</li><li><strong>日志修剪问题</strong>: 同步策略导致即使某些区域不同步数据，也会查询这些区域，从而阻止日志被修剪。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ul><li><strong>同步策略问题</strong>: 讨论了同步策略在多区域配置中的实现问题，包括数据同步和日志修剪策略。</li><li><strong>rgwhttp 客户端问题</strong>: 探讨了新 HTTP 客户端在多站点环境中的潜在好处和与 SSL 库的兼容性问题。</li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>Reef 分支分叉</strong>: 通过分叉 Reef 发布分支，所有后续改动需合并至 Main 并通过 backboards。</li><li><strong>同步策略问题</strong>: 需要进一步审查和测试同步策略，特别是关于数据同步和日志修剪的逻辑。</li><li><strong>rgwhttp 客户端问题</strong>: 需要解决与 SSL 库的兼容性问题，以便在多站点环境中使用。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>同步策略审查</strong>: Yehuda 将审查同步策略的实现，并测试更多案例以确认和解决存在的问题。</li><li><strong>rgwhttp 客户端开发</strong>: 继续开发和测试 rgwhttp 客户端，特别是在处理 SSL 库兼容性方面的工作。</li><li><strong>问题跟踪</strong>: 所有相关问题和讨论将被记录在 Tracker 和 Theta pad 中，以便后续跟踪和解决。</li></ul>',9)])])}const p=e(i,[["render",n]]);export{c as __pageData,p as default};
